<?php
session_start();
require_once 'dbconfig.php';
$doctorId=(int)($_SESSION['doctor_id']??0); if($doctorId<=0){header('Location: Admin/dlogin.php');exit;}
$stmtDoctor=$conn->prepare("SELECT did,name,username FROM doctor WHERE did=? LIMIT 1");$stmtDoctor->bind_param('i',$doctorId);$stmtDoctor->execute();$doctor=$stmtDoctor->get_result()->fetch_assoc();$stmtDoctor->close();
if(!$doctor){session_destroy();die('Doktor bulunamadı.');}
$selectedDate=$_GET['date']??date('Y-m-d');$dateObj=DateTime::createFromFormat('Y-m-d',$selectedDate);if(!$dateObj||$dateObj->format('Y-m-d')!==$selectedDate){$selectedDate=date('Y-m-d');$dateObj=new DateTime($selectedDate);}
$stmt=$conn->prepare("SELECT b.appointment_id,b.Fname,b.Gender,b.appointment_time,b.DOV,b.Status,b.Timestamp,c.name AS clinic_name,c.town FROM book b LEFT JOIN clinic c ON c.CID=b.CID WHERE b.DID=? AND b.DOV=? ORDER BY b.appointment_time ASC,b.Timestamp ASC");$stmt->bind_param('is',$doctorId,$selectedDate);$stmt->execute();$appointments=$stmt->get_result();
$weekStart=new DateTime($selectedDate);$weekStart->modify('monday this week');$weekEnd=clone $weekStart;$weekEnd->modify('+6 days');$ws=$weekStart->format('Y-m-d');$we=$weekEnd->format('Y-m-d');
$stmtWeek=$conn->prepare("SELECT DOV,COUNT(*) total FROM book WHERE DID=? AND DOV BETWEEN ? AND ? GROUP BY DOV");$stmtWeek->bind_param('iss',$doctorId,$ws,$we);$stmtWeek->execute();$weekResult=$stmtWeek->get_result();$weekCounts=[];while($r=$weekResult->fetch_assoc())$weekCounts[$r['DOV']]=(int)$r['total'];$stmtWeek->close();
function statusClass($s){return ['Onaylandı'=>'approved','Tamamlandı'=>'completed','İptal Edildi'=>'cancelled'][$s]??'pending';}function statusLabel($s){$s=trim((string)$s);return($s===''||$s==='Booked')?'Bekliyor':$s;}$appointmentCount=$appointments->num_rows;
?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Doktor Paneli</title><link rel="stylesheet" href="main.css"><style>
.doctor-shell{min-height:100vh;background:radial-gradient(circle at 90% 0,#e9f2ff 0,transparent 32%),var(--page)}.doctor-top{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.96);backdrop-filter:blur(12px);border-bottom:1px solid var(--border)}.doctor-top-inner{width:min(1180px,calc(100% - 32px));min-height:72px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:20px}.doctor-brand{font-size:21px;font-weight:850;color:var(--text)}.doctor-brand span{color:var(--primary)}.doctor-user{display:flex;align-items:center;gap:11px}.doctor-avatar{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:var(--primary);color:#fff;font-weight:850}.doctor-user small{margin:0;color:var(--muted)}.doctor-main{width:min(1180px,calc(100% - 32px));margin:34px auto 70px}.doctor-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.doctor-heading h1{margin:0;font-size:32px}.doctor-heading p{margin:7px 0 0}.doctor-logout{color:var(--danger);background:var(--danger-bg);border:1px solid #f0c5c5;padding:10px 15px;border-radius:10px;font-weight:800}.doctor-date{padding:20px;margin-bottom:18px}.doctor-date form{display:flex;align-items:end;gap:12px}.doctor-date .field{flex:1}.doctor-date label{display:block;margin-bottom:7px;font-size:13px;font-weight:800}.doctor-date input{margin:0}.doctor-date button{width:auto;margin:0}.week-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:10px;margin-bottom:28px}.week-day{background:#fff;border:1px solid var(--border);border-radius:14px;padding:13px 7px;text-align:center;transition:.2s}.week-day:hover{border-color:#9fc2f3;transform:translateY(-2px)}.week-day.active{background:var(--primary);border-color:var(--primary);color:#fff;box-shadow:0 8px 22px rgba(23,105,224,.2)}.week-day .name{font-size:11px;font-weight:850}.week-day .date{font-size:18px;font-weight:850;margin:4px 0}.week-day .count{font-size:11px;opacity:.75}.appointments-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.appointments-head h2{margin:0}.appointment-list{display:grid;gap:12px}.appointment-item{display:grid;grid-template-columns:88px minmax(0,1fr) auto;align-items:center;gap:20px;padding:20px;background:#fff;border:1px solid var(--border);border-radius:16px;box-shadow:0 5px 18px rgba(25,45,80,.035)}.appointment-item:hover{border-color:#d1ddeb;box-shadow:0 10px 25px rgba(25,45,80,.07)}.appointment-time{font-size:23px;font-weight:900;color:var(--primary)}.patient-name{font-size:16px;font-weight:850}.patient-meta{margin-top:5px;color:var(--muted);font-size:13px}.status-area{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap}.status{display:inline-flex;padding:7px 11px;border-radius:999px;font-size:12px;font-weight:800}.status.pending{background:var(--warning-bg);color:var(--warning)}.status.approved{background:var(--success-bg);color:var(--success)}.status.completed{background:#e9f1ff;color:#185abc}.status.cancelled{background:var(--danger-bg);color:var(--danger)}.actions{display:flex;gap:6px}.action{min-height:38px;padding:8px 11px;border-radius:9px;border:1px solid transparent;font-size:12px;font-weight:800;cursor:pointer}.action.approve{background:#e9f7ef;color:var(--success)}.action.complete{background:#e9f1ff;color:#185abc}.action.cancel{background:var(--danger-bg);color:var(--danger)}.action:hover{transform:translateY(-1px)}.empty{padding:55px 20px;text-align:center}.empty strong{display:block;color:var(--text);margin-bottom:6px}@media(max-width:850px){.week-grid{grid-template-columns:repeat(4,1fr)}.appointment-item{grid-template-columns:75px 1fr}.status-area{grid-column:1/-1;justify-content:flex-start;padding-top:12px;border-top:1px solid var(--border)}}@media(max-width:600px){.doctor-top-inner,.doctor-main{width:calc(100% - 20px)}.doctor-user{display:none}.doctor-heading{align-items:flex-start}.doctor-heading h1{font-size:25px}.doctor-date form{flex-direction:column;align-items:stretch}.doctor-date button{width:100%}.week-grid{grid-template-columns:repeat(2,1fr)}.appointment-item{grid-template-columns:1fr;gap:10px}.status-area{grid-column:auto}.doctor-logout{padding:9px 11px}}
</style></head><body><div class="doctor-shell"><header class="doctor-top"><div class="doctor-top-inner"><div class="doctor-brand">Appointment <span>· Doktor</span></div><div class="doctor-user"><div class="doctor-avatar"><?php echo htmlspecialchars(strtoupper(substr($doctor['name'],0,1)),ENT_QUOTES,'UTF-8'); ?></div><div><strong><?php echo htmlspecialchars($doctor['name'],ENT_QUOTES,'UTF-8'); ?></strong><small>Doktor Paneli</small></div></div></div></header><main class="doctor-main"><section class="doctor-heading"><div><span class="eyebrow">DOKTOR PANELİ</span><h1>Merhaba, Dr. <?php echo htmlspecialchars($doctor['name'],ENT_QUOTES,'UTF-8'); ?></h1><p><?php echo $dateObj->format('d.m.Y'); ?> tarihli randevularınız</p></div><a class="doctor-logout" href="doctor_logout.php">Çıkış Yap</a></section><section class="card doctor-date"><form method="get"><div class="field"><label for="date">Randevu tarihi</label><input id="date" type="date" name="date" value="<?php echo htmlspecialchars($selectedDate,ENT_QUOTES,'UTF-8'); ?>"></div><button type="submit">Takvimi Göster</button></form></section><section class="week-grid"><?php $days=['Mon'=>'Pzt','Tue'=>'Sal','Wed'=>'Çar','Thu'=>'Per','Fri'=>'Cum','Sat'=>'Cmt','Sun'=>'Paz'];for($i=0;$i<7;$i++):$d=clone $weekStart;$d->modify("+$i day");$ds=$d->format('Y-m-d');?><a class="week-day <?php echo $ds===$selectedDate?'active':''; ?>" href="doctor_dashboard.php?date=<?php echo $ds; ?>"><div class="name"><?php echo $days[$d->format('D')]; ?></div><div class="date"><?php echo $d->format('d.m'); ?></div><div class="count"><?php echo $weekCounts[$ds]??0; ?> randevu</div></a><?php endfor;?></section><section><div class="appointments-head"><h2>Randevular</h2><span class="status-pill status-completed"><?php echo $appointmentCount; ?> randevu</span></div><div class="appointment-list"><?php if(!$appointmentCount):?><div class="card empty"><strong>Randevu bulunmuyor</strong>Seçtiğiniz tarihte planlanmış bir randevu yok.</div><?php else:while($row=$appointments->fetch_assoc()):$st=statusLabel($row['Status']);?><article class="appointment-item" data-appointment-id="<?php echo (int)$row['appointment_id']; ?>"><div class="appointment-time"><?php echo htmlspecialchars(substr((string)$row['appointment_time'],0,5),ENT_QUOTES,'UTF-8'); ?></div><div><div class="patient-name"><?php echo htmlspecialchars($row['Fname'],ENT_QUOTES,'UTF-8'); ?></div><div class="patient-meta"><?php echo htmlspecialchars($row['Gender'],ENT_QUOTES,'UTF-8'); ?> · <?php echo htmlspecialchars($row['clinic_name']??'Klinik',ENT_QUOTES,'UTF-8'); ?><?php if(!empty($row['town']))echo ' · '.htmlspecialchars($row['town'],ENT_QUOTES,'UTF-8');?></div></div><div class="status-area"><span class="status <?php echo statusClass($st); ?>" data-status><?php echo htmlspecialchars($st,ENT_QUOTES,'UTF-8'); ?></span><div class="actions" data-actions><?php if($st==='Bekliyor'):?><button class="action approve" data-status-action="Onaylandı" type="button">Onayla</button><button class="action cancel" data-status-action="İptal Edildi" type="button">İptal Et</button><?php elseif($st==='Onaylandı'):?><button class="action complete" data-status-action="Tamamlandı" type="button">Tamamlandı</button><button class="action cancel" data-status-action="İptal Edildi" type="button">İptal Et</button><?php endif;?></div></div></article><?php endwhile;endif;?></div></section></main></div><script>(function(){async function updateStatus(b){const c=b.closest('.appointment-item'),id=c.dataset.appointmentId,status=b.dataset.statusAction;if(status==='İptal Edildi'&&!confirm('Bu randevuyu iptal etmek istediğinize emin misiniz?'))return;c.querySelectorAll('[data-status-action]').forEach(x=>x.disabled=true);try{const r=await fetch('doctor_update_status.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8','X-Requested-With':'XMLHttpRequest'},body:new URLSearchParams({appointment_id:id,status})});const d=await r.json();if(!r.ok||!d.success)throw Error(d.message||'Güncelleme başarısız.');c.querySelector('[data-status]').textContent=d.status;const map={Onaylandı:'approved',Tamamlandı:'completed','İptal Edildi':'cancelled',Bekliyor:'pending'};c.querySelector('[data-status]').className='status '+(map[d.status]||'pending');c.querySelector('[data-actions]').innerHTML=d.status==='Onaylandı'?'<button class="action complete" data-status-action="Tamamlandı" type="button">Tamamlandı</button><button class="action cancel" data-status-action="İptal Edildi" type="button">İptal Et</button>':'';}catch(e){alert(e.message);c.querySelectorAll('[data-status-action]').forEach(x=>x.disabled=false);}}document.addEventListener('click',e=>{const b=e.target.closest('[data-status-action]');if(b)updateStatus(b);});})();</script></body></html>